#include "stdlib/lapack/base/dpstf2.h"
#include "stdlib/lapack/base/shared.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>

#define ITERATIONS 200
#define REPEATS 2

/**
* Returns a clock time in seconds.
*
* @return clock time
*/
static double tic( void ) {
	struct timeval now;
	gettimeofday( &now, NULL );
	return (double)now.tv_sec + (double)now.tv_usec/1.0e6;
}

/**
* Resets and factors a bounded matrix, then validates its outputs.
*
* @param N          matrix order
* @param uplo       selected triangle
* @param ndarray    whether to use explicit indexing
* @param truncated  whether to stop using a cutoff after the first step
* @return           elapsed seconds or -1 on failure
*/
static double benchmark( const LAPACK_INT N, const LAPACK_UPLO uplo, const int ndarray, const int truncated ) {
	double *original;
	double *WORK;
	double *A;
	LAPACK_INT *PIV;
	LAPACK_INT RANK;
	LAPACK_INT expectedRank;
	LAPACK_INT expectedInfo;
	LAPACK_INT info;
	LAPACK_INT i;
	LAPACK_INT j;
	double elapsed;
	double tol;
	double t;
	int k;

	original = (double *)malloc( (size_t)(N*N) * sizeof( double ) );
	A = (double *)malloc( (size_t)(N*N) * sizeof( double ) );
	WORK = (double *)malloc( (size_t)(2*N) * sizeof( double ) );
	PIV = (LAPACK_INT *)malloc( (size_t)N * sizeof( LAPACK_INT ) );
	if ( original == NULL || A == NULL || WORK == NULL || PIV == NULL ) {
		fprintf( stderr, "Error allocating bounded benchmark buffers.\n" );
		free( original );
		free( A );
		free( WORK );
		free( PIV );
		return -1.0;
	}
	for ( i = 0; i < N; i++ ) {
		PIV[ i ] = -99;
		for ( j = 0; j < N; j++ ) {
			if ( i == j ) {
				original[ (i*N)+j ] = (double)N + 2.0;
			} else if ( ( uplo == LAPACK_UPPER_TRIANGLE && i < j ) || ( uplo == LAPACK_LOWER_TRIANGLE && i > j ) ) {
				original[ (i*N)+j ] = 0.25;
			} else {
				original[ (i*N)+j ] = 999.0;
			}
		}
	}
	for ( i = 0; i < 2*N; i++ ) {
		WORK[ i ] = -9.0;
	}
	expectedRank = truncated ? 1 : N;
	expectedInfo = truncated ? 1 : 0;
	tol = truncated ? (double)N+2.0 : -1.0;
	RANK = -9;
	info = -9;
	t = tic();
	for ( k = 0; k < ITERATIONS; k++ ) {
		// Include resetting the changed input in the measured workload:
		memcpy( A, original, (size_t)(N*N) * sizeof( double ) );
		if ( ndarray ) {
			info = API_SUFFIX(c_dpstf2_ndarray)( uplo, N, A, N, 1, 0, PIV, 1, 0, &RANK, 0, tol, WORK, 1, 0 );
		} else {
			info = API_SUFFIX(c_dpstf2)( LAPACK_ROW_MAJOR, uplo, N, A, N, PIV, &RANK, tol, WORK );
		}
		if ( info != expectedInfo || RANK != expectedRank ) {
			break;
		}
	}
	elapsed = tic() - t;
	if ( info != expectedInfo || RANK != expectedRank ) {
		elapsed = -1.0;
	}
	for ( i = 0; i < N; i++ ) {
		if ( PIV[ i ] != i+1 ) {
			elapsed = -1.0;
		}
		for ( j = 0; j < N; j++ ) {
			if ( ( uplo == LAPACK_UPPER_TRIANGLE && i > j ) || ( uplo == LAPACK_LOWER_TRIANGLE && i < j ) ) {
				if ( A[ (i*N)+j ] != 999.0 ) {
					elapsed = -1.0;
				}
			}
		}
	}
	free( original );
	free( A );
	free( WORK );
	free( PIV );
	return elapsed;
}

/**
* Main execution sequence.
*/
int main( void ) {
	const LAPACK_INT sizes[] = { 8, 16 };
	const LAPACK_UPLO uplos[] = { LAPACK_UPPER_TRIANGLE, LAPACK_LOWER_TRIANGLE };
	double elapsed;
	int count;
	int passing;
	int i;
	int j;
	int k;
	int truncated;
	int r;

	count = 0;
	passing = 0;
	printf( "TAP version 13\n" );
	for ( i = 0; i < 2; i++ ) {
		for ( j = 0; j < 2; j++ ) {
			for ( k = 0; k < 2; k++ ) {
				for ( truncated = 0; truncated < 2; truncated++ ) {
					for ( r = 0; r < REPEATS; r++ ) {
						count += 1;
						printf( "# c::dpstf2:N=%d:uplo=%s:ndarray=%d:cutoff=%s\n", (int)sizes[ i ], j ? "lower" : "upper", k, truncated ? "user" : "default" );
						elapsed = benchmark( sizes[ i ], uplos[ j ], k, truncated );
						if ( elapsed < 0.0 ) {
							printf( "not ok %d benchmark failed\n", count );
						} else {
							printf( "  ---\n" );
							printf( "  iterations: %d\n", ITERATIONS );
							printf( "  elapsed: %0.9f\n", elapsed );
							printf( "  ...\n" );
							printf( "ok %d benchmark finished\n", count );
							passing += 1;
						}
					}
				}
			}
		}
	}
	printf( "1..%d\n", count );
	printf( "# total %d\n", count );
	printf( "# pass  %d\n", passing );
	if ( passing == count ) {
		printf( "# ok\n" );
		return EXIT_SUCCESS;
	}
	return EXIT_FAILURE;
}
